mapper.select:
select * from (
select row_number() over (order by allowd_id) as rn
 allowd_id, ad.department_id, department_name 
from allow_departments ad 
left join department d 
on ad.department_id = d.department_id

where department_name = #{searchWord}

) as sub where rn between #{startRow} and #{endRow}

mapper.update:
update allowd_departments
set department_id=#{departmentId}
where allowd_id=#{allowdId}
